35	/// script the next `create()` result and count how many times it was
36	/// called (I/O matrix: "Cancel before save ... no `POST /entries` fires").
37	class _FakeEntriesRepository implements EntriesRepository {
38	  Either<Failure, Entry> Function()? nextResult;
39	  int createCallCount = 0;
